import sys

def make_tree(depth):
    if depth > 0:
        return [make_tree(depth - 1), make_tree(depth - 1)]
    return [None, None]

def check_tree(node):
    left = node[0]
    if left is None:
        return 1
    return 1 + check_tree(left) + check_tree(node[1])

def main():
    n = int(sys.argv[1])
    min_depth = 4
    max_depth = n
    stretch_depth = max_depth + 1
    print("stretch tree of depth %d\t check: %d" % (
        stretch_depth, check_tree(make_tree(stretch_depth))))
    long_lived_tree = make_tree(max_depth)
    for depth in range(min_depth, max_depth + 1, 2):
        iterations = 1 << (max_depth - depth + min_depth)
        check = 0
        for _ in range(iterations):
            check += check_tree(make_tree(depth))
        print("%d\t trees of depth %d\t check: %d" % (iterations, depth, check))
    print("long lived tree of depth %d\t check: %d" % (
        max_depth, check_tree(long_lived_tree)))

if __name__ == "__main__":
    main()
```

