#!/usr/bin/env python3
import sys
from collections import defaultdict


def read_three_sequence():
    data = sys.stdin.read()
    p = data.find(">THREE")
    if p >= 0:
        p = data.find("\n", p)
        data = data[p + 1 :]
    chunks = []
    for line in data.splitlines():
        if line.startswith(">"):
            break
        chunks.append(line)
    return "".join(chunks).upper()


def kmer_counts(seq, k):
    n = len(seq) - k + 1
    counts = defaultdict(int)
    for i in range(n):
        counts[seq[i : i + k]] += 1
    return counts, n


def print_frequencies(seq, k):
    counts, n = kmer_counts(seq, k)
    items = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    for mer, c in items:
        print("%s %.3f" % (mer, (100.0 * c) / n))
    print()


def count_overlapping(seq, sub):
    count = 0
    start = 0
    while True:
        pos = seq.find(sub, start)
        if pos < 0:
            return count
        count += 1
        start = pos + 1


def main():
    int(sys.argv[1])  # harness always passes N; sequence is on stdin
    seq = read_three_sequence()
    print_frequencies(seq, 1)
    print_frequencies(seq, 2)
    for frag in (
        "GGT",
        "GGTA",
        "GGTATT",
        "GGTATTTTAATT",
        "GGTATTTTAATTTATAGT",
    ):
        print("%d\t%s" % (count_overlapping(seq, frag), frag))


if __name__ == "__main__":
    main()
```
